from __future__ import annotations

import base64
import hashlib
import zlib

_SOURCE_SHA256 = "300ea83063f290f7772273a01c9ce79639a397b0bd69accb7ebbd5f8bd416119"
_SOURCE_ZLIB_BASE64 = ""

_source = zlib.decompress(base64.b64decode(_SOURCE_ZLIB_BASE64))
_actual = hashlib.sha256(_source).hexdigest()
if _actual != _SOURCE_SHA256:
    raise RuntimeError(f"embedded source hash mismatch: expected={_SOURCE_SHA256} actual={_actual}")
exec(compile(_source, __file__, "exec"), globals(), globals())
